internal static class StandaloneTests {
 internal const string Sample=@"{""data"":{""guide"":{""url"":""parcours-exemple"",""title"":""Parcours fictif de validation"",""description"":""<p>Données de test uniquement</p>"",""objectives"":[{""id"":1,""type"":""title"",""payload"":{""fr"":""Zone de test""}},{""id"":2,""type"":""note"",""payload"":{""fr"":""Point de test [-1,2]""}},{""id"":3,""type"":""quest"",""payload"":10},{""id"":4,""type"":""group"",""payload"":[{""id"":5,""type"":""quest"",""payload"":10}]},{""id"":6,""type"":""choice"",""payload"":[{""condition"":""Classe=Sacri"",""objectives"":[{""id"":7,""type"":""quest"",""payload"":11}]},{""condition"":""Classe=Iop"",""objectives"":[{""id"":8,""type"":""quest"",""payload"":12}]}]}]},""quests"":{""10"":{""name"":{""fr"":""Première quête fictive""},""dplnUrl"":""https://example.com/guide"",""prerequisites"":[{""type"":""quest"",""id"":11}],""objectives"":[{""type"":""note"",""payload"":{""fr"":""Instruction de test""}}],""items"":[{""count"":3,""item"":{""id"":500,""name"":{""fr"":""Ressource fictive""}}}]},""11"":{""name"":{""fr"":""Branche Sacrieur fictive""},""objectives"":[],""items"":[]},""12"":{""name"":{""fr"":""Branche Iop fictive""},""objectives"":[],""items"":[]}},""achievements"":{}}}";
 static void Check(bool condition,string text){if(!condition)throw new Exception(text);}
 static System.Collections.Generic.IEnumerable<T> Find<T>(DependencyObject parent) where T:DependencyObject {if(parent is T)yield return (T)parent;for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent);i++)foreach(var item in Find<T>(System.Windows.Media.VisualTreeHelper.GetChild(parent,i)))yield return item;}
 internal static int Run(string folder){Directory.CreateDirectory(folder);try{var store=new Store(Path.Combine(folder,"isolated-data"));var a=new DofusCharacter{id="a",name="Personnage test",classCode="Sacri",alignment="Bonta",order="CV",guide="parcours-exemple"};var b=new DofusCharacter{id="b",name="Autre personnage",classCode="Iop",guide=a.guide};store.Value.dofus.characters.AddRange(new[]{a,b});store.Value.dofus.active=a.id;store.Save();TougliReader.Cache(store,a.guide,Sample);var doc=TougliReader.Parse(Sample,a);Check(doc.Steps.Count==4&&doc.Steps.Last().Title.Contains("Sacrieur"),"Lecture et choix classe");Check(DofusCompanion.Remaining(store.Value,doc).Single().Count==3,"Déduplication ressources");Check(!TougliReader.Parse(Sample,new DofusCharacter()).Steps.Last().CanComplete,"Choix absent deviné");Check(TougliReader.SafeUrl("javascript:alert(1)")==""&&!TougliReader.ValidSlug("../a"),"Liens et cache");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new CompanionWindow(store,true);window.Render(Path.Combine(folder,"overlay.png"));var finish=Find<Button>(window.Content as DependencyObject).First(x=>Equals(x.Content,"Terminé →"));finish.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(DofusCompanion.Find(store.Value,a).done.Count==1,"Bouton réel valider");Check(DofusCompanion.Current(store.Value,doc).Title.Contains("Première quête"),"Navigation réelle");window.Render(Path.Combine(folder,"overlay-next.png"));DofusCompanion.Toggle(store,doc);Check(DofusCompanion.Find(store.Value,a).done.Count==2,"Validation");DofusCompanion.Toggle(store,doc);Check(DofusCompanion.Find(store.Value,a).done.Count==1,"Annulation");store.Value.dofus.active=b.id;store.Save();Check(DofusCompanion.Find(store.Value,b)==null,"Indépendance personnage");Check(TougliReader.Parse(Sample,b).Steps.Last().Title.Contains("Iop"),"Autre classe");store.Value.dofus.active=a.id;store.Save();var reopened=new Store(store.Root);Check(DofusCompanion.Find(reopened.Value,DofusCompanion.Character(reopened.Value)).done.Count==1,"Reprise sauvegarde");var tmp=Path.Combine(store.Root,"state.json.tmp");Directory.CreateDirectory(tmp);bool failed=false;try{DofusCompanion.Toggle(store,doc);}catch(IOException){failed=true;}catch(UnauthorizedAccessException){failed=true;}Directory.Delete(tmp);Check(failed&&DofusCompanion.Find(store.Value,DofusCompanion.Character(store.Value)).done.Count==1,"Retour arrière écriture échouée");store.Save();var empty=new CompanionWindow(new Store(Path.Combine(folder,"empty")),true);empty.Render(Path.Combine(folder,"welcome.png"));Check(Find<Button>(empty.Content as DependencyObject).Any(x=>Equals(x.Content,"Personnage · Guides")),"Configuration accessible sans guide");window.Close();empty.Close();app.Shutdown();File.WriteAllText(Path.Combine(folder,"PASS.txt"),"PASS: native WPF render; real completion button; API fixture; class selection; unresolved choices; resources; undo; separate characters; restart; failed-save rollback; welcome configuration. No MonEspace data access. Windows installer shortcuts and real game topmost need a user desktop check.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"FAIL.txt"),ex.ToString());return 1;}}
}
